import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {Link} from '@primer/react'

import {GeneralSettings} from '../components/GeneralSettings'
import {ApprovalsSection} from '../components/ApprovalsSection'
import {AutomatedRulesetsSection} from '../components/AutomatedRulesetsSection'
import {CodingGuidelinesSection} from '../components/CodingGuidelinesSection'
import type {CopilotCodeReviewRepoSettingsPayload} from '../types'

const PAGE_TITLE = 'Copilot Code review'

export function RepoSettings() {
  const payload = useRoutePayload<CopilotCodeReviewRepoSettingsPayload>()
  const {endpoints, learnMoreUrl, generalSettings, approvalSettings, rulesets, codingGuidelines} = payload
  const qualifiedApprovalEndpoint = endpoints.qualifiedApproval

  return (
    <div>
      <div className="d-flex flex-items-center flex-justify-between gap-2 width-full border-bottom pb-2 tmp-mb-3">
        <h2 className="Subhead-heading Subhead-heading--large">{PAGE_TITLE}</h2>
      </div>

      <p className="mb-0">
        With Copilot code review, you can add Copilot as a reviewer to your pull requests, including drafts. You can
        also select lines in Visual Studio Code and ask Copilot to review and comment on specific sections.{' '}
        <Link href={learnMoreUrl} inline>
          Learn more about Copilot code reviews.
        </Link>
      </p>

      <GeneralSettings settingsEndpoint={endpoints.settings} initialValue={generalSettings} />

      {approvalSettings !== undefined && qualifiedApprovalEndpoint !== undefined && (
        <ApprovalsSection
          settingsEndpoint={endpoints.settings}
          qualifiedApprovalEndpoint={qualifiedApprovalEndpoint}
          initialValue={approvalSettings}
        />
      )}

      <AutomatedRulesetsSection rulesets={rulesets} />

      <CodingGuidelinesSection codingGuidelines={codingGuidelines} />
    </div>
  )
}
