import {useMutation, type UseMutationResult} from '@github-ui/react-query'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'

import type {QualifiedApprovalScopeWhenEnabled} from '../types'

type UpdateQualifiedApprovalSettingsArgs = {
  scopeWhenEnabled: QualifiedApprovalScopeWhenEnabled
  filePatterns: string
}

export function useUpdateQualifiedApprovalSettings(
  endpoint: string,
): UseMutationResult<void, Error, UpdateQualifiedApprovalSettingsArgs> {
  return useMutation({
    mutationFn: async ({scopeWhenEnabled, filePatterns}: UpdateQualifiedApprovalSettingsArgs) => {
      const response = await verifiedFetchJSON(endpoint, {
        method: 'PUT',
        body: {
          repo_qualified_approval_scope_when_enabled: scopeWhenEnabled,
          qualified_approval_file_patterns: filePatterns,
        },
      })

      if (!response.ok) {
        let data: {error?: string; message?: string} | null = null
        try {
          data = (await response.json()) as {error?: string; message?: string}
        } catch {
          // ignore parse errors
        }
        const message = data?.error ?? data?.message ?? `Failed to update qualified approval settings`
        throw new Error(message)
      }
    },
  })
}
