import {useMutation, type UseMutationResult} from '@github-ui/react-query'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'

import type {BooleanSettingKey, ReviewEffortLevel} from '../types'

type UpdateSettingArgs =
  | {setting: BooleanSettingKey; value: boolean}
  | {setting: 'repo_review_effort_level'; value: ReviewEffortLevel}

function settingUrl(endpoint: string, setting: string): string {
  const url = new URL(endpoint, window.location.origin)
  url.searchParams.set('setting', setting)
  return url.pathname + url.search
}

function serializeValue(args: UpdateSettingArgs): string {
  if (args.setting === 'repo_review_effort_level') return args.value
  return args.value ? '1' : '0'
}

export function useUpdateCodeReviewSetting(endpoint: string): UseMutationResult<void, Error, UpdateSettingArgs> {
  return useMutation({
    mutationFn: async (args: UpdateSettingArgs) => {
      const response = await verifiedFetchJSON(settingUrl(endpoint, args.setting), {
        method: 'POST',
        body: {value: serializeValue(args)},
      })

      if (!response.ok) {
        let data: {error?: string; message?: string} | null = null
        try {
          data = (await response.json()) as {error?: string; message?: string}
        } catch {
          // ignore parse errors
        }
        const message =
          data?.error ?? data?.message ?? `Failed to update ${args.setting}: ${response.status} ${response.statusText}`
        throw new Error(message)
      }
    },
  })
}
