import {ControlGroup} from '@github-ui/control-group'
import {BetaLabel} from '@github-ui/lifecycle-labels/beta'
import {ActionList, ActionMenu, Heading, Label, Link, Stack} from '@primer/react'
import {InlineMessage} from '@primer/react/experimental'
import {useState, type ReactNode} from 'react'

import {useUpdateCodeReviewSetting} from '../hooks/useUpdateCodeReviewSetting'
import type {BooleanSettingKey, GeneralSettingsPayload, ReviewEffortLevel} from '../types'

type Props = {
  settingsEndpoint: string
  initialValue: GeneralSettingsPayload
}

export function GeneralSettings({settingsEndpoint, initialValue}: Props) {
  const sectionVisible =
    initialValue.customInstructionsFeatureEnabled ||
    initialValue.autoRejectFeatureEnabled ||
    initialValue.mcpFeatureEnabled ||
    initialValue.reviewEffortLevelFeatureEnabled

  if (!sectionVisible) return null

  return (
    <div className="tmp-mt-4">
      <Heading as="h3" variant="small">
        General settings
      </Heading>
      <Stack className="tmp-mt-3" gap="condensed">
        <ControlGroup>
          {initialValue.customInstructionsFeatureEnabled && (
            <BooleanSetting
              settingsEndpoint={settingsEndpoint}
              settingKey="repo_custom_instructions_enabled"
              initialValue={initialValue.customInstructionsEnabled}
              labelId="ccr-custom-instructions-label"
              descriptionId="ccr-custom-instructions-description"
              title="Use custom instructions when reviewing pull requests"
              description={
                <>
                  Copilot references{' '}
                  <Link href={initialValue.customInstructionsDocsUrl} inline>
                    repository custom instructions
                  </Link>{' '}
                  when reviewing pull requests.
                </>
              }
            />
          )}

          {initialValue.autoRejectFeatureEnabled && (
            <BooleanSetting
              settingsEndpoint={settingsEndpoint}
              settingKey="repo_auto_reject_enabled"
              initialValue={initialValue.autoRejectEnabled}
              labelId="ccr-auto-reject-label"
              descriptionId="ccr-auto-reject-description"
              title="Automatically request changes when Copilot determines updates are required"
            />
          )}

          {initialValue.mcpFeatureEnabled && (
            <BooleanSetting
              settingsEndpoint={settingsEndpoint}
              settingKey="repo_mcp_enabled"
              initialValue={initialValue.mcpEnabled}
              labelId="ccr-mcp-label"
              descriptionId="ccr-mcp-description"
              title="Allow Copilot to use MCP tools when reviewing pull requests"
              badge={<BetaLabel className="ml-2" />}
              description={
                <>
                  When enabled, Copilot can call MCP tools configured in{' '}
                  <Link href={initialValue.codingAgentSettingsUrl} inline>
                    {initialValue.codingAgentSettingsLabel}
                  </Link>{' '}
                  during code reviews.
                </>
              }
            />
          )}

          {initialValue.reviewEffortLevelFeatureEnabled && (
            <ReviewEffortLevelSetting
              settingsEndpoint={settingsEndpoint}
              initialValue={initialValue.reviewEffortLevel}
            />
          )}
        </ControlGroup>
      </Stack>
    </div>
  )
}

type BooleanSettingProps = {
  settingsEndpoint: string
  settingKey: BooleanSettingKey
  initialValue: boolean
  labelId: string
  descriptionId: string
  title: ReactNode
  badge?: ReactNode
  description?: ReactNode
}

function BooleanSetting({
  settingsEndpoint,
  settingKey,
  initialValue,
  labelId,
  descriptionId,
  title,
  badge,
  description,
}: BooleanSettingProps) {
  const saveSetting = useUpdateCodeReviewSetting(settingsEndpoint)
  const [enabled, setEnabled] = useState<boolean>(initialValue)
  const [errorMessage, setErrorMessage] = useState<string | null>(null)
  const isSaving = saveSetting.isPending

  const handleToggle = async () => {
    if (isSaving) return
    const next = !enabled
    setEnabled(next)
    setErrorMessage(null)
    try {
      await saveSetting.mutateAsync({setting: settingKey, value: next})
    } catch (error) {
      setEnabled(!next)
      setErrorMessage(error instanceof Error ? error.message : 'An error occurred saving this setting.')
    }
  }

  return (
    <ControlGroup.Item>
      <ControlGroup.Title>
        <span id={labelId}>{title}</span>
        {badge}
      </ControlGroup.Title>
      <ControlGroup.Description id={descriptionId}>
        {description}
        <div role="status" aria-live="polite">
          {errorMessage && (
            <InlineMessage variant="critical" size="small" className={description !== undefined ? 'mt-1' : undefined}>
              {errorMessage}
            </InlineMessage>
          )}
        </div>
      </ControlGroup.Description>
      <ControlGroup.ToggleSwitch
        aria-labelledby={labelId}
        aria-describedby={descriptionId}
        checked={enabled}
        disabled={isSaving}
        onClick={() => {
          handleToggle()
        }}
      />
    </ControlGroup.Item>
  )
}

const REVIEW_EFFORT_OPTIONS: Array<{
  value: ReviewEffortLevel
  label: string
  description: string
  badge?: ReactNode
  disabled?: boolean
}> = [
  {value: 'low', label: 'Low', description: 'Standard review, lowest cost'},
  {
    value: 'medium',
    label: 'Medium',
    description: 'Deeper analysis, higher cost',
    badge: <BetaLabel />,
  },
  {
    value: 'high',
    label: 'High',
    description: 'Most thorough, highest cost',
    badge: <Label>Coming soon</Label>,
    disabled: true,
  },
]

function ReviewEffortLevelSetting({
  settingsEndpoint,
  initialValue,
}: {
  settingsEndpoint: string
  initialValue: ReviewEffortLevel
}) {
  const saveSetting = useUpdateCodeReviewSetting(settingsEndpoint)
  const [value, setValue] = useState<ReviewEffortLevel>(initialValue)
  const [errorMessage, setErrorMessage] = useState<string | null>(null)
  const isSaving = saveSetting.isPending
  const labelId = 'ccr-review-effort-level-label'
  const descriptionId = 'ccr-review-effort-level-description'

  const currentLabel = REVIEW_EFFORT_OPTIONS.find(o => o.value === value)?.label ?? 'Low'

  const handleSelect = async (next: ReviewEffortLevel) => {
    if (next === value || isSaving) return
    const previous = value
    setValue(next)
    setErrorMessage(null)
    try {
      await saveSetting.mutateAsync({setting: 'repo_review_effort_level', value: next})
    } catch (error) {
      setValue(previous)
      setErrorMessage(error instanceof Error ? error.message : 'An error occurred saving this setting.')
    }
  }

  const valueId = 'ccr-review-effort-level-value'

  return (
    <ControlGroup.Item>
      <ControlGroup.Title>
        <span id={labelId}>Review effort level</span>
        <Label className="ml-2">New</Label>
      </ControlGroup.Title>
      <ControlGroup.Description id={descriptionId}>
        Controls the depth of analysis when Copilot reviews pull requests.
        <div role="status" aria-live="polite">
          {errorMessage && (
            <InlineMessage variant="critical" size="small" className="mt-1">
              {errorMessage}
            </InlineMessage>
          )}
        </div>
      </ControlGroup.Description>
      <ControlGroup.Custom>
        <ActionMenu>
          <ActionMenu.Button
            aria-labelledby={`${labelId} ${valueId}`}
            aria-describedby={descriptionId}
            variant="invisible"
            disabled={isSaving}
          >
            <span id={valueId}>{currentLabel}</span>
          </ActionMenu.Button>
          <ActionMenu.Overlay align="end">
            <ActionList selectionVariant="single">
              {REVIEW_EFFORT_OPTIONS.map(option => (
                <ActionList.Item
                  key={option.value}
                  selected={option.value === value}
                  disabled={option.disabled || isSaving}
                  className="pr-4"
                  onSelect={() => {
                    if (option.disabled || isSaving) return
                    handleSelect(option.value)
                  }}
                >
                  <span>
                    {option.label}
                    {option.badge ? <span className="ml-2">{option.badge}</span> : null}
                  </span>
                  <ActionList.Description variant="block">{option.description}</ActionList.Description>
                </ActionList.Item>
              ))}
            </ActionList>
          </ActionMenu.Overlay>
        </ActionMenu>
      </ControlGroup.Custom>
    </ControlGroup.Item>
  )
}
