import {Button, Checkbox, FormControl, Textarea} from '@primer/react'
import {InlineMessage} from '@primer/react/experimental'
import {useState, type FormEvent} from 'react'

import {useUpdateQualifiedApprovalSettings} from '../hooks/useUpdateQualifiedApprovalSettings'
import type {QualifiedApprovalScopeWhenEnabled} from '../types'

type Props = {
  endpoint: string
  initialScopeWhenEnabled: QualifiedApprovalScopeWhenEnabled
  initialFilePatterns: string
  maxFilePatternCount: number
  onSaved?: (settings: {scopeWhenEnabled: QualifiedApprovalScopeWhenEnabled; filePatterns: string}) => void
}

export function QualifiedApprovalFilePatternsForm({
  endpoint,
  initialScopeWhenEnabled,
  initialFilePatterns,
  maxFilePatternCount,
  onSaved,
}: Props) {
  const saveSettings = useUpdateQualifiedApprovalSettings(endpoint)
  const [limitToFilePatterns, setLimitToFilePatterns] = useState(initialScopeWhenEnabled === 'file_patterns')
  const [filePatterns, setFilePatterns] = useState(initialFilePatterns)
  const [message, setMessage] = useState<{variant: 'success' | 'critical'; text: string} | null>(null)
  const isSaving = saveSettings.isPending

  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    setMessage(null)

    const scopeWhenEnabled: QualifiedApprovalScopeWhenEnabled = limitToFilePatterns ? 'file_patterns' : 'all_files'
    const nextFilePatterns = limitToFilePatterns ? filePatterns : ''

    try {
      await saveSettings.mutateAsync({scopeWhenEnabled, filePatterns: nextFilePatterns})
      setFilePatterns(nextFilePatterns)
      setMessage({variant: 'success', text: 'Saved approval file path settings.'})
      onSaved?.({scopeWhenEnabled, filePatterns: nextFilePatterns})
    } catch (error) {
      setMessage({
        variant: 'critical',
        text: error instanceof Error ? error.message : 'An error occurred saving approval file path settings.',
      })
    }
  }

  return (
    <form className="width-full" onSubmit={handleSubmit}>
      <FormControl disabled={isSaving}>
        <Checkbox
          checked={limitToFilePatterns}
          onChange={event => {
            setLimitToFilePatterns(event.target.checked)
            setMessage(null)
          }}
        />
        <FormControl.Label>Limit to file paths</FormControl.Label>
        <FormControl.Caption>
          Count Copilot approvals toward merge requirements only when every changed file matches one of the saved file
          globs.
        </FormControl.Caption>
      </FormControl>

      {limitToFilePatterns && (
        <FormControl className="tmp-mt-3" disabled={isSaving}>
          <FormControl.Label>File globs</FormControl.Label>
          <Textarea
            block
            rows={4}
            value={filePatterns}
            placeholder={'*.md\n/docs/**\nfrontend/*.ts'}
            onChange={event => {
              setFilePatterns(event.target.value)
              setMessage(null)
            }}
          />
          <FormControl.Caption>
            Enter one file glob per line. Up to {maxFilePatternCount} globs are supported.
          </FormControl.Caption>
        </FormControl>
      )}

      <p className="note tmp-mt-3 tmp-mb-0">Save to apply the limit option and any file glob changes.</p>

      <div className="tmp-mt-3 d-flex flex-items-center gap-2">
        <Button type="submit" variant="primary" disabled={isSaving}>
          {isSaving ? 'Saving...' : 'Save changes'}
        </Button>
        <div role="status" aria-live="polite">
          {message && (
            <InlineMessage variant={message.variant} size="small">
              {message.text}
            </InlineMessage>
          )}
        </div>
      </div>
    </form>
  )
}
